from typing import TypedDict, Unpack

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class StatusReply(TypedDict):
    sn: str
    type: str
    media: str
    text: str


class StatusSetKwargs(TypedDict):
    media: str
    text: str
    duration: int
    reply: dict[str, StatusReply]


class StatusesMethods(BaseClient):
    """
    Методы группы 'Статусы' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=51)
    @tracer.start_as_current_span("statuses.rapi_status_set")
    def rapi_status_set(self, _type: str, **kwargs: Unpack[StatusSetKwargs]) -> dict:
        r"""
        Метод для установки статуса пользователя.
        :param _type: Тип статуса (empty/predefined/emoji)
        param media: Медиа-часть статуса, содержимое зависит от типа \n
        param text: Текстовая часть статуса \n
        param duration: Продолжительность действия статуса (в секундах) \n
        param reply_sn: SN пользователя, на статус которого отправляется ответ \n
        param reply_type: Тип статуса, на который отправляется ответ \n
        param reply_media: Медиа-часть статуса, на который отправляется ответ \n
        param reply_text: Текстовая часть статуса,
        на который отправляется ответ \n
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/status/set",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"type": _type, **kwargs},
            },
        )

    @api_version_check(min_version=51)
    @tracer.start_as_current_span("statuses.rapi_status_set")
    def rapi_status_list(self, _hash: str, lang: str = "RU") -> dict:
        """
        Метод для получения списка статусов.
        :param _hash: хэш имеющегося у клиента списка статусов
        :param lang: локаль
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/status/list",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"hash": _hash, "lang": lang},
            },
        )
